#!/usr/bin/env bash
# One-click installer for SpaceSync on Linux (Lokinya's Linux port + Ukrainian translation).
# Generated by AI (Claude, Anthropic). SpaceSync is AGPL-3.0, see NOTICE.md.
#
#   Install / update:  curl -fsSL https://raw.githubusercontent.com/lokinyauv-create/OpenVR-SpaceSync/lokinya-build/get.sh | bash
#   Uninstall:         curl -fsSL https://raw.githubusercontent.com/lokinyauv-create/OpenVR-SpaceSync/lokinya-build/get.sh | bash -s -- --uninstall
set -euo pipefail
REPO="lokinyauv-create/OpenVR-SpaceSync"
ASSET="SpaceSync-linux-x86_64.tar.gz"
APP="$HOME/.local/opt/SpaceSync"

if [ "${1:-}" = "--uninstall" ]; then
  if [ -x "$APP/uninstall.sh" ]; then
    exec "$APP/uninstall.sh"
  fi
  echo "SpaceSync is not installed. / SpaceSync не встановлено."
  exit 0
fi

if pgrep -x vrserver >/dev/null || pgrep -x vrmonitor >/dev/null; then
  echo "Close SteamVR first, then run this again. / Спершу закрий SteamVR, потім запусти ще раз."
  exit 2
fi

for tool in curl tar python3; do
  command -v "$tool" >/dev/null || { echo "Missing: $tool / Бракує: $tool"; exit 1; }
done

tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT
echo "• Downloading / Завантажую SpaceSync"
curl -fL --progress-bar -o "$tmp/$ASSET" "https://github.com/$REPO/releases/latest/download/$ASSET"
tar -xzf "$tmp/$ASSET" -C "$tmp"
bash "$tmp/SpaceSync-linux/linux/install.sh"
# Release tag, so VR Auto Launcher can tell which version is installed.
[ -f "$tmp/SpaceSync-linux/VERSION" ] && cp "$tmp/SpaceSync-linux/VERSION" "$APP/VERSION" || true
